@startuml

class OilWell {
  + code : string
}

abstract class WellCategory {}

class OnshoreWell {
  + surfaceExtension : float
}

class OffshoreWell {
  + installationYear : int
}

class Company {
  + taxCode : string
  + numberOfEmployees : int
}

class Extraction {
  + quantityMillionsBarrels : float
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

OilWell --|> WellCategory
OnshoreWell --|> OilWell
OffshoreWell --|> OilWell

OilWell "1" *-- "0..*" Extraction
Extraction "*" -- "1" Company
Extraction "*" -- "1" OilWell

OffshoreWell "0..1" o-- "1" GeographicalArea

@enduml

